    def improve(self, shifts: list[Shift], hours_cap: float | None, max_sweeps: int = 30) -> list[Shift]:
        """Deterministic first-improvement hill climb over single-shift moves: drop a shift, change
        its template, day or queue, or add a shift for an agent with spare hours. Objective,
        lexicographic: floor shortfalls, intervals short of the weekly attainment target, unmet
        operating intervals, understaffed agent-intervals, scheduled hours. Hours never exceed
        `hours_cap`."""
        by_id = {a.agent_id: a for a in self.agents}
        shifts = list(shifts)
        per_q = {q: [sh for sh in shifts if sh.queue == q] for q in self.queues}
        qscore = {q: self.score_queue(q, per_q[q]) for q in self.queues}
        hours = sum(sh.hours for sh in shifts)

        def total(qs, h):
            return tuple(sum(v[i] for v in qs.values()) for i in range(4)) + (h,)

        current = total(qscore, hours)

        def mk(agent_id, q, tpl, day):
            return Shift(agent_id, q, tpl, day, list(self.tpl_segs[tpl.id, day]), list(self.tpl_ivs[tpl.id, day]))

        def try_move(old: Shift | None, new: Shift | None) -> bool:
